def list_tables(workspace_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0372000" if __import__("os").path.isdir("./environment_mix/0372000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = re.sub(r"[^A-Z2-7]", "A", token)
        return f"{prefix}_{token[:18]}"

    def _redact(obj):
        secret_keys = {
            "authorization", "x-api-key", "api_key", "apikey", "token", "access_token",
            "secret", "password", "private_key", "session"
        }
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if lk in secret_keys or "secret" in lk or "token" in lk or "password" in lk or lk.endswith("_key"):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj]
        return obj

    def _encode_cursor(payload):
        b = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        try:
            pad = "=" * ((4 - (len(cur) % 4)) % 4)
            b = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(b.decode("utf-8"))
        except Exception:
            return None

    def _log(operation, status, ws_id, api_key_id, table_id, request_params, http_status_code=None,
             error_code=None, error_message=None, response_summary=None, pagination_token_row_id=None):
        now = _now_utc()
        read_requests = _load("read_requests.json")
        rid = _gen_id("rrq")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": rid,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "table_id": table_id,
            "operation": operation,
            "status": status,
            "request_params": _redact(request_params) if isinstance(request_params, dict) else {},
            "response_summary": response_summary,
            "result_items_sample": None,
            "pagination_token_id": pagination_token_row_id,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": (error_message[:300] if isinstance(error_message, str) else error_message),
            "duration_ms": duration_ms,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        read_requests.append(row)
        _save("read_requests.json", read_requests)
        return rid

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^wsp_[0-9A-Z]{18,}$", workspace_id):
        # Can't resolve workspace; still log as rejected with ambient api_key=None
        _log("list-tables", "rejected", workspace_id if isinstance(workspace_id, str) else "", None, None,
             {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
             http_status_code=400, error_code="ValidationError", error_message="workspace_id is malformed.")
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")

    if status is not None and status not in ("active", "deleted", "inaccessible"):
        _log("list-tables", "rejected", workspace_id, None, None,
             {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
             http_status_code=400, error_code="ValidationError", error_message="status is invalid.")
        return _err("VALIDATION_ERROR", "status is invalid. Must be one of: active, deleted, inaccessible.")
    if sort is not None and sort not in ("table_name", "created_at", "updated_at", "last_described_at"):
        _log("list-tables", "rejected", workspace_id, None, None,
             {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
             http_status_code=400, error_code="ValidationError", error_message="sort is invalid.")
        return _err("VALIDATION_ERROR", "sort is invalid.")
    if order is not None and order not in ("asc", "desc"):
        _log("list-tables", "rejected", workspace_id, None, None,
             {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
             http_status_code=400, error_code="ValidationError", error_message="order is invalid.")
        return _err("VALIDATION_ERROR", "order is invalid.")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 1000):
        _log("list-tables", "rejected", workspace_id, None, None,
             {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
             http_status_code=400, error_code="ValidationError", error_message="limit is out of range.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.")

    cur = _decode_cursor(cursor) if cursor else None
    if cursor is not None and cursor != "" and cur is None:
        _log("list-tables", "rejected", workspace_id, None, None,
             {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
             http_status_code=400, error_code="ValidationError", error_message="cursor is invalid.")
        return _err("VALIDATION_ERROR", "cursor is invalid.")

    # Load store
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tables = _load("dynamodb_tables.json")
    read_requests = _load("read_requests.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("list-tables", "rejected", workspace_id, None, None,
             {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
             http_status_code=404, error_code="WorkspaceNotFound", error_message="Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")

    # Ambient auth: must have active workspace + active api key for it
    api_key = None
    if ws.get("status") == "active":
        for k in api_keys:
            if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active":
                api_key = k
                break

    if ws.get("status") != "active" or not api_key:
        _log("list-tables", "rejected", workspace_id, api_key.get("id") if api_key else None, None,
             {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
             http_status_code=401, error_code="Unauthorized", error_message="Workspace or API key is inactive.")
        return _err("UNAUTHORIZED", "Workspace or API key is inactive.")

    # Rate limit: count read_requests with status in received/succeeded/failed within last rolling minute
    now = _now_utc()
    window_start = now - datetime.timedelta(seconds=60)
    active_statuses = {"received", "succeeded", "failed"}
    recent = 0
    for r in read_requests:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("status") not in active_statuses:
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt and dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt and dt >= window_start:
            recent += 1
    if isinstance(ws.get("max_requests_per_minute"), int) and recent >= ws.get("max_requests_per_minute"):
        _log("list-tables", "rejected", workspace_id, api_key.get("id"), None,
             {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
             http_status_code=429, error_code="Throttling", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded for workspace.")

    # Apply business rule: list-tables returns active catalog rows filtered by workspace and status='active' regardless of status filter
    # Tool supports optional status filter, but business rule mandates status='active'.
    filtered = [t for t in tables if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("status") == "active"]
    # If caller additionally requests status, it can only ever be 'active' per rule; other statuses yield empty set.
    if status is not None:
        filtered = [t for t in filtered if t.get("status") == status]

    # Sorting/pagination
    sort_field = sort or "table_name"
    reverse = (order == "desc")

    def _sort_key(row):
        v = row.get(sort_field)
        if sort_field in ("created_at", "updated_at", "last_described_at"):
            dt = _parse_dt(v)
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            return v.lower()
        return "" if v is None else str(v)

    filtered.sort(key=_sort_key, reverse=reverse)

    start = 0
    if cur:
        if cur.get("workspace_id") != workspace_id or cur.get("sort") != sort_field or cur.get("order") != (order or "asc") or cur.get("status") != status:
            _log("list-tables", "rejected", workspace_id, api_key.get("id"), None,
                 {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
                 http_status_code=409, error_code="CursorConflict", error_message="cursor does not match the current query context.")
            return _err("CONFLICT", "cursor does not match the current query context.")
        if isinstance(cur.get("offset"), int) and cur["offset"] >= 0:
            start = cur["offset"]

    page_limit = limit if limit is not None else 100
    end = start + page_limit
    page = filtered[start:end]
    has_more = end < len(filtered)
    next_cursor = _encode_cursor({"workspace_id": workspace_id, "offset": end, "sort": sort_field, "order": (order or "asc"), "status": status}) if has_more else None

    # Log success
    _log("list-tables", "succeeded", workspace_id, api_key.get("id"), None,
         {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "order": order},
         http_status_code=200,
         response_summary={"count": len(page), "total": len(filtered), "has_more": has_more})

    # Update api key last_used_at on success
    api_keys_all = api_keys
    for k in api_keys_all:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys_all)

    return {"tables": page, "total": len(filtered), "has_more": has_more, "next_cursor": next_cursor}

def describe_table(workspace_id, table_id=None, table_name=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0372000" if __import__("os").path.isdir("./environment_mix/0372000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = re.sub(r"[^A-Z2-7]", "A", token)
        return f"{prefix}_{token[:18]}"

    def _redact(obj):
        secret_keys = {
            "authorization", "x-api-key", "api_key", "apikey", "token", "access_token",
            "secret", "password", "private_key", "session"
        }
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if lk in secret_keys or "secret" in lk or "token" in lk or "password" in lk or lk.endswith("_key"):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj]
        return obj

    def _reqlog(status, ws_id, api_key_id, table_id_log, request_params, http_status_code=None,
                error_code=None, error_message=None, response_summary=None):
        read_requests = _load("read_requests.json")
        now = _now()
        rid = _gen_id("rrq")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": rid,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "table_id": table_id_log,
            "operation": "describe-table",
            "status": status,
            "request_params": _redact(request_params) if isinstance(request_params, dict) else {},
            "response_summary": response_summary,
            "result_items_sample": None,
            "pagination_token_id": None,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": (error_message[:300] if isinstance(error_message, str) else error_message),
            "duration_ms": duration_ms,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        read_requests.append(row)
        _save("read_requests.json", read_requests)
        return rid

    # Validate workspace_id
    if not isinstance(workspace_id, str) or not re.match(r"^wsp_[0-9A-Z]{18,}$", workspace_id):
        _reqlog("rejected", workspace_id if isinstance(workspace_id, str) else "", None, None,
                {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name},
                http_status_code=400, error_code="ValidationError", error_message="workspace_id is malformed.")
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")

    # Identifiers: accept either/both; if both provided, prefer table_id and ensure consistency if table_name also set
    if table_id is None and table_name is None:
        _reqlog("rejected", workspace_id, None, None,
                {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name},
                http_status_code=400, error_code="ValidationError", error_message="Either table_id or table_name is required.")
        return _err("VALIDATION_ERROR", "Provide at least one of table_id or table_name.")
    if table_id is not None and (not isinstance(table_id, str) or not re.match(r"^ddb_tbl_[0-9A-Z]{18,}$", table_id)):
        _reqlog("rejected", workspace_id, None, None,
                {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name},
                http_status_code=400, error_code="ValidationError", error_message="table_id is malformed.")
        return _err("VALIDATION_ERROR", "table_id is malformed.")
    if table_name is not None and (not isinstance(table_name, str) or len(table_name) < 1):
        _reqlog("rejected", workspace_id, None, None,
                {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name},
                http_status_code=400, error_code="ValidationError", error_message="table_name must be a non-empty string.")
        return _err("VALIDATION_ERROR", "table_name must be a non-empty string.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tables = _load("dynamodb_tables.json")
    read_requests = _load("read_requests.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _reqlog("rejected", workspace_id, None, None,
                {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name},
                http_status_code=404, error_code="WorkspaceNotFound", error_message="Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")

    # Ambient auth
    api_key = None
    if ws.get("status") == "active":
        for k in api_keys:
            if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active":
                api_key = k
                break
    if ws.get("status") != "active" or not api_key:
        _reqlog("rejected", workspace_id, api_key.get("id") if api_key else None, None,
                {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name},
                http_status_code=401, error_code="Unauthorized", error_message="Workspace or API key is inactive.")
        return _err("UNAUTHORIZED", "Workspace or API key is inactive.")

    # Rate limit
    now = _now()
    window_start = now - datetime.timedelta(seconds=60)
    active_statuses = {"received", "succeeded", "failed"}
    recent = 0
    for r in read_requests:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("status") not in active_statuses:
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt and dt >= window_start:
            recent += 1
    if isinstance(ws.get("max_requests_per_minute"), int) and recent >= ws.get("max_requests_per_minute"):
        _reqlog("rejected", workspace_id, api_key.get("id"), None,
                {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name},
                http_status_code=429, error_code="Throttling", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded for workspace.")

    # Resolve table
    table = None
    if table_id is not None:
        table = next((t for t in tables if isinstance(t, dict) and t.get("id") == table_id and t.get("workspace_id") == workspace_id), None)
        if table and table_name is not None and table.get("table_name") != table_name:
            _reqlog("failed", workspace_id, api_key.get("id"), table_id,
                    {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name},
                    http_status_code=409, error_code="IdentifierMismatch", error_message="table_id and table_name refer to different tables.")
            return _err("CONFLICT", "table_id and table_name refer to different tables.")
    else:
        table = next((t for t in tables if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("table_name") == table_name), None)

    if not table:
        _reqlog("failed", workspace_id, api_key.get("id"), table_id,
                {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name},
                http_status_code=404, error_code="TableNotFound", error_message="Table not found in workspace catalog.")
        return _err("NOT_FOUND", "Table not found in workspace catalog.")

    # Simulate "refresh TTL" without AWS: if stale, just update last_described_at (no external calls offline)
    TTL_SECONDS = 3600
    last_desc = _parse_dt(table.get("last_described_at")) if table.get("last_described_at") else None
    if last_desc is None or (now - last_desc).total_seconds() > TTL_SECONDS:
        # Refresh snapshot timestamp; do not fabricate metadata
        for t in tables:
            if isinstance(t, dict) and t.get("id") == table.get("id"):
                t["last_described_at"] = _iso(now)
                t["updated_at"] = _iso(now)
                table = t
                break
        _save("dynamodb_tables.json", tables)

    _reqlog("succeeded", workspace_id, api_key.get("id"), table.get("id"),
            {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name},
            http_status_code=200,
            response_summary={"status": table.get("status"), "last_described_at": table.get("last_described_at")})

    # Update api key last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys)

    return {"table": table}

def scan_table(workspace_id, table_id=None, table_name=None, limit=None, consistent_read=None, projection_expression=None, filter_expression=None, expression_attribute_names=None, expression_attribute_values=None, pagination_token_id=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0372000" if __import__("os").path.isdir("./environment_mix/0372000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return _iso(datetime.datetime.now(datetime.timezone.utc))
    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    def _gen_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = re.sub(r"[^A-Z2-7]", "A", token)
        return f"{prefix}_{token[:18]}"
    def _fingerprint(payload):
        b = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()
    def _redact(obj):
        secret_keys = {"authorization", "x-api-key", "api_key", "apikey", "token", "access_token", "secret", "password", "private_key", "session"}
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if lk in secret_keys or "secret" in lk or "token" in lk or "password" in lk or lk.endswith("_key"):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj]
        return obj

    def _log_request(operation, status, ws_id, api_key_id, table_id_log, request_params, http_status_code=None,
                     error_code=None, error_message=None, response_summary=None, result_items_sample=None, pagination_token_row_id=None):
        rr = _load("read_requests.json")
        if isinstance(rr, dict) and "rows" in rr: rr_rows = rr.get("rows", [])
        elif isinstance(rr, list): rr_rows = rr
        else: rr_rows = []
        rid = _gen_id("req")  # datastore examples use req_*
        duration_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": rid,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "table_id": table_id_log,
            "operation": operation,
            "status": status,
            "request_params": _redact(request_params if isinstance(request_params, dict) else {}),
            "response_summary": response_summary,
            "result_items_sample": result_items_sample,
            "pagination_token_id": pagination_token_row_id,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "duration_ms": duration_ms,
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        rr_rows.append(row)
        _save("read_requests.json", rr_rows)
        return row

    # ---------- validate basic types/patterns ----------
    if not isinstance(workspace_id, str) or not re.match(r"^wsp_[0-9A-Z]{18,}$", workspace_id):
        _log_request("scan-table", "rejected", workspace_id if isinstance(workspace_id, str) else "wsp_INVALID", None, None,
                     {"workspace_id": workspace_id}, http_status_code=400, error_code="ValidationError", error_message="Malformed workspace_id.")
        return _err("VALIDATION_ERROR", "Malformed workspace_id.")
    if table_id is not None and (not isinstance(table_id, str) or not re.match(r"^ddb_tbl_[0-9A-Z]{18,}$", table_id)):
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "table_id": table_id}, http_status_code=400, error_code="ValidationError", error_message="Malformed table_id.")
        return _err("VALIDATION_ERROR", "Malformed table_id.")
    if pagination_token_id is not None and (not isinstance(pagination_token_id, str) or not re.match(r"^ptok_[0-9A-Z]{18,}$", pagination_token_id)):
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "pagination_token_id": pagination_token_id}, http_status_code=400, error_code="ValidationError", error_message="Malformed pagination_token_id.")
        return _err("VALIDATION_ERROR", "Malformed pagination_token_id.")
    if table_name is not None and (not isinstance(table_name, str) or len(table_name) < 1):
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "table_name": table_name}, http_status_code=400, error_code="ValidationError", error_message="Invalid table_name.")
        return _err("VALIDATION_ERROR", "Invalid table_name.")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "limit": limit}, http_status_code=400, error_code="ValidationError", error_message="Invalid limit.")
        return _err("VALIDATION_ERROR", "Invalid limit.")
    if consistent_read is not None and not isinstance(consistent_read, bool):
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "consistent_read": consistent_read}, http_status_code=400, error_code="ValidationError", error_message="Invalid consistent_read.")
        return _err("VALIDATION_ERROR", "Invalid consistent_read.")
    if projection_expression is not None and not isinstance(projection_expression, str):
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "projection_expression": projection_expression}, http_status_code=400, error_code="ValidationError", error_message="Invalid projection_expression.")
        return _err("VALIDATION_ERROR", "Invalid projection_expression.")
    if filter_expression is not None and not isinstance(filter_expression, str):
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "filter_expression": filter_expression}, http_status_code=400, error_code="ValidationError", error_message="Invalid filter_expression.")
        return _err("VALIDATION_ERROR", "Invalid filter_expression.")
    if expression_attribute_names is not None:
        if not isinstance(expression_attribute_names, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in expression_attribute_names.items()):
            _log_request("scan-table", "rejected", workspace_id, None, None,
                         {"workspace_id": workspace_id, "expression_attribute_names": expression_attribute_names}, http_status_code=400, error_code="ValidationError", error_message="Invalid expression_attribute_names.")
            return _err("VALIDATION_ERROR", "Invalid expression_attribute_names.")
    if expression_attribute_values is not None and not isinstance(expression_attribute_values, dict):
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "expression_attribute_values": expression_attribute_values}, http_status_code=400, error_code="ValidationError", error_message="Invalid expression_attribute_values.")
        return _err("VALIDATION_ERROR", "Invalid expression_attribute_values.")

    # ---------- load state ----------
    wss = _load("workspaces.json")
    if isinstance(wss, dict) and "rows" in wss: wrows = wss.get("rows", [])
    elif isinstance(wss, list): wrows = wss
    else: wrows = []
    ws = next((w for w in wrows if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id}, http_status_code=404, error_code="NotFound", error_message="Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id}, http_status_code=401, error_code="Unauthorized", error_message="Workspace is not active.")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    keys = _load("api_keys.json")
    if isinstance(keys, dict) and "rows" in keys: krows = keys.get("rows", [])
    elif isinstance(keys, list): krows = keys
    else: krows = []
    # ambient auth: choose any active key in this workspace
    api_key = next((k for k in krows if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not api_key:
        _log_request("scan-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id}, http_status_code=401, error_code="Unauthorized", error_message="No active API key for workspace.")
        return _err("UNAUTHORIZED", "No active API key for workspace.")

    # rate limiting: count requests in last rolling minute for this workspace with statuses in ('received','succeeded','failed')
    rr = _load("read_requests.json")
    if isinstance(rr, dict) and "rows" in rr: rr_rows = rr.get("rows", [])
    elif isinstance(rr, list): rr_rows = rr
    else: rr_rows = []
    window_start = now - datetime.timedelta(seconds=60)
    count_in_window = 0
    for r in rr_rows:
        if not isinstance(r, dict): 
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("status") not in ("received", "succeeded", "failed"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt and dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt and dt >= window_start:
            count_in_window += 1
    mrpm = ws.get("max_requests_per_minute")
    if not isinstance(mrpm, int) or mrpm < 1:
        mrpm = 60
    if count_in_window >= mrpm:
        _log_request("scan-table", "rejected", workspace_id, api_key.get("id"), None,
                     {"workspace_id": workspace_id}, http_status_code=429, error_code="Throttling", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", max_requests_per_minute=mrpm)

    # enforce max_page_size
    max_page = ws.get("max_page_size")
    if not isinstance(max_page, int) or max_page < 1:
        max_page = 100
    eff_limit = limit if limit is not None else max_page
    if eff_limit > max_page:
        _log_request("scan-table", "rejected", workspace_id, api_key.get("id"), None,
                     {"workspace_id": workspace_id, "limit": limit}, http_status_code=400, error_code="ValidationError", error_message="limit exceeds workspace max_page_size.",
                     response_summary={"max_page_size": max_page})
        return _err("VALIDATION_ERROR", "limit exceeds workspace max_page_size.", max_page_size=max_page)

    # resolve table (relax: accept either matching id OR matching name; if both provided and conflict, prefer id)
    tables = _load("dynamodb_tables.json")
    if isinstance(tables, dict) and "rows" in tables: trows = tables.get("rows", [])
    elif isinstance(tables, list): trows = tables
    else: trows = []

    resolved = None
    if isinstance(table_id, str):
        resolved = next((t for t in trows if isinstance(t, dict) and t.get("id") == table_id), None)
    if not resolved and isinstance(table_name, str):
        resolved = next((t for t in trows if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("table_name") == table_name), None)
    # If still not resolved but table_id exists elsewhere, accept it even if workspace mismatch (caller may pass wrong workspace_id)
    # BUT do not leak across workspaces: require workspace match to proceed.
    if not resolved:
        _log_request("scan-table", "failed", workspace_id, api_key.get("id"), table_id,
                     {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name, "limit": eff_limit}, http_status_code=404,
                     error_code="NotFound", error_message="Table not found in workspace catalog.")
        return _err("NOT_FOUND", "Table not found in workspace catalog.")
    if resolved.get("workspace_id") != workspace_id:
        _log_request("scan-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                     {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name}, http_status_code=401,
                     error_code="Unauthorized", error_message="Table does not belong to workspace.")
        return _err("UNAUTHORIZED", "Table does not belong to workspace.")
    if resolved.get("status") != "active":
        _log_request("scan-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                     {"workspace_id": workspace_id, "table_id": resolved.get("id")}, http_status_code=409,
                     error_code="InvalidState", error_message="Table is not active.")
        return _err("INVALID_TRANSITION", "Table is not active for scanning.", table_status=resolved.get("status"))

    # pagination token handling (if provided, validate belongs to workspace & operation and not expired)
    pagination_tokens = _load("pagination_tokens.json")
    if isinstance(pagination_tokens, dict) and "rows" in pagination_tokens: prows = pagination_tokens.get("rows", [])
    elif isinstance(pagination_tokens, list): prows = pagination_tokens
    else: prows = []

    # Build request params payload (stored verbatim-ish but redacted)
    req_params = {
        "workspace_id": workspace_id,
        "table_id": resolved.get("id"),
        "table_name": resolved.get("table_name"),
        "limit": eff_limit,
        "consistent_read": consistent_read,
        "projection_expression": projection_expression,
        "filter_expression": filter_expression,
        "expression_attribute_names": expression_attribute_names,
        "expression_attribute_values": expression_attribute_values,
        "pagination_token_id": pagination_token_id,
    }
    # fingerprint used to detect token reuse mismatch
    scan_ctx = {
        "workspace_id": workspace_id,
        "table_id": resolved.get("id"),
        "table_name": resolved.get("table_name"),
        "projection_expression": projection_expression,
        "filter_expression": filter_expression,
        "expression_attribute_names": expression_attribute_names or {},
        "expression_attribute_values": expression_attribute_values or {},
        "consistent_read": consistent_read,
        "operation": "scan-table",
    }
    fp = _fingerprint(scan_ctx)

    token_row = None
    if pagination_token_id is not None:
        token_row = next((p for p in prows if isinstance(p, dict) and p.get("id") == pagination_token_id), None)
        if not token_row:
            _log_request("scan-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"), req_params,
                         http_status_code=404, error_code="NotFound", error_message="Pagination token not found.")
            return _err("NOT_FOUND", "Pagination token not found.")
        if token_row.get("workspace_id") != workspace_id:
            _log_request("scan-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"), req_params,
                         http_status_code=409, error_code="Conflict", error_message="Pagination token does not belong to this workspace.")
            return _err("CONFLICT", "Pagination token does not belong to this workspace.")
        if token_row.get("operation") != "scan-table" and token_row.get("operation") != "scan-table".replace("-", "-"):
            # datastore uses ('query-table','scan-table') per schema; enforce it
            if token_row.get("operation") != "scan-table":
                _log_request("scan-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"), req_params,
                             http_status_code=409, error_code="Conflict", error_message="Pagination token is not for scan-table.")
                return _err("CONFLICT", "Pagination token is not for scan-table.")
        if token_row.get("status") != "active":
            _log_request("scan-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"), req_params,
                         http_status_code=409, error_code="Conflict", error_message="Pagination token is not active.")
            return _err("CONFLICT", "Pagination token is not active.", token_status=token_row.get("status"))
        exp = _parse_dt(token_row.get("expires_at"))
        if not exp:
            _log_request("scan-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"), req_params,
                         http_status_code=409, error_code="Conflict", error_message="Pagination token is invalid.")
            return _err("CONFLICT", "Pagination token is invalid.")
        if exp.tzinfo is None:
            exp = exp.replace(tzinfo=datetime.timezone.utc)
        if exp <= now:
            # mark expired
            token_row["status"] = "expired"
            token_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            _save("pagination_tokens.json", prows)
            _log_request("scan-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"), req_params,
                         http_status_code=409, error_code="Conflict", error_message="Pagination token expired.", pagination_token_row_id=token_row.get("id"))
            return _err("CONFLICT", "Pagination token expired.")
        if token_row.get("query_fingerprint") and token_row.get("query_fingerprint") != fp:
            _log_request("scan-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"), req_params,
                         http_status_code=409, error_code="Conflict", error_message="Pagination token reused with different scan context.", pagination_token_row_id=token_row.get("id"))
            return _err("CONFLICT", "pagination_token_id reused with different scan context (fingerprint mismatch).")

    # Simulated scan result (read-only server): return empty items but correct envelopes and token mechanics.
    # If a token is provided, consume it (single-use) and potentially mint a next token.
    items = []
    scanned_count = 0
    returned_count = 0

    new_token_id = None
    # deterministic "has more" based on presence/absence of token: first page returns a token, subsequent page no token
    has_more = pagination_token_id is None

    if token_row is not None:
        token_row["status"] = "consumed"
        token_row["consumed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        token_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("pagination_tokens.json", prows)

    if has_more:
        new_token_id = _gen_id("ptok")
        token_hash = hashlib.sha256((new_token_id + ":opaque").encode("utf-8")).hexdigest()
        expires_at = now + datetime.timedelta(minutes=10)
        prows.append({
            "id": new_token_id,
            "workspace_id": workspace_id,
            "table_id": resolved.get("id"),
            "operation": "scan-table",
            "status": "active",
            "token_hash": token_hash,
            "encrypted_last_evaluated_key": base64.b64encode(os.urandom(24)).decode("ascii"),
            "query_fingerprint": fp,
            "expires_at": _iso(expires_at),
            "consumed_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        })
        _save("pagination_tokens.json", prows)

    # update api key last_used_at on success
    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", krows)

    resp_summary = {
        "count": returned_count,
        "scanned_count": scanned_count,
        "last_evaluated_key_present": bool(new_token_id),
        "limit": eff_limit,
    }
    _log_request("scan-table", "succeeded", workspace_id, api_key.get("id"), resolved.get("id"), req_params,
                 http_status_code=200, response_summary=resp_summary,
                 result_items_sample=[], pagination_token_row_id=new_token_id)

    return {
        "workspace_id": workspace_id,
        "table_id": resolved.get("id"),
        "table_name": resolved.get("table_name"),
        "items": items,
        "count": returned_count,
        "scanned_count": scanned_count,
        "pagination_token_id": new_token_id,
        "limit": eff_limit,
    }

def query_table(workspace_id, table_id=None, table_name=None, index_name=None, key_condition_expression=None, filter_expression=None, projection_expression=None, expression_attribute_names=None, expression_attribute_values=None, limit=None, scan_index_forward=None, consistent_read=None, pagination_token_id=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0372000" if __import__("os").path.isdir("./environment_mix/0372000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return _iso(datetime.datetime.now(datetime.timezone.utc))
    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    def _gen_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = re.sub(r"[^A-Z2-7]", "A", token)
        return f"{prefix}_{token[:18]}"
    def _fingerprint(payload):
        b = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()
    def _redact(obj):
        secret_keys = {"authorization", "x-api-key", "api_key", "apikey", "token", "access_token", "secret", "password", "private_key", "session"}
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if lk in secret_keys or "secret" in lk or "token" in lk or "password" in lk or lk.endswith("_key"):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj]
        return obj
    def _log_request(operation, status, ws_id, api_key_id, table_id_log, request_params, http_status_code=None,
                     error_code=None, error_message=None, response_summary=None, result_items_sample=None, pagination_token_row_id=None):
        rr = _load("read_requests.json")
        if isinstance(rr, dict) and "rows" in rr: rr_rows = rr.get("rows", [])
        elif isinstance(rr, list): rr_rows = rr
        else: rr_rows = []
        rid = _gen_id("req")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": rid,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "table_id": table_id_log,
            "operation": operation,
            "status": status,
            "request_params": _redact(request_params if isinstance(request_params, dict) else {}),
            "response_summary": response_summary,
            "result_items_sample": result_items_sample,
            "pagination_token_id": pagination_token_row_id,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "duration_ms": duration_ms,
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        rr_rows.append(row)
        _save("read_requests.json", rr_rows)
        return row

    # validation
    if not isinstance(workspace_id, str) or not re.match(r"^wsp_[0-9A-Z]{18,}$", workspace_id):
        _log_request("query-table", "rejected", workspace_id if isinstance(workspace_id, str) else "wsp_INVALID", None, None,
                     {"workspace_id": workspace_id}, http_status_code=400, error_code="ValidationError", error_message="Malformed workspace_id.")
        return _err("VALIDATION_ERROR", "Malformed workspace_id.")
    if table_id is not None and (not isinstance(table_id, str) or not re.match(r"^ddb_tbl_[0-9A-Z]{18,}$", table_id)):
        _log_request("query-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "table_id": table_id}, http_status_code=400, error_code="ValidationError", error_message="Malformed table_id.")
        return _err("VALIDATION_ERROR", "Malformed table_id.")
    if table_name is not None and (not isinstance(table_name, str) or len(table_name) < 1):
        _log_request("query-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "table_name": table_name}, http_status_code=400, error_code="ValidationError", error_message="Invalid table_name.")
        return _err("VALIDATION_ERROR", "Invalid table_name.")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        _log_request("query-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "limit": limit}, http_status_code=400, error_code="ValidationError", error_message="Invalid limit.")
        return _err("VALIDATION_ERROR", "Invalid limit.")
    if scan_index_forward is not None and not isinstance(scan_index_forward, bool):
        _log_request("query-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "scan_index_forward": scan_index_forward}, http_status_code=400, error_code="ValidationError", error_message="Invalid scan_index_forward.")
        return _err("VALIDATION_ERROR", "Invalid scan_index_forward.")
    if consistent_read is not None and not isinstance(consistent_read, bool):
        _log_request("query-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "consistent_read": consistent_read}, http_status_code=400, error_code="ValidationError", error_message="Invalid consistent_read.")
        return _err("VALIDATION_ERROR", "Invalid consistent_read.")
    if key_condition_expression is not None and not isinstance(key_condition_expression, str):
        _log_request("query-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "key_condition_expression": key_condition_expression}, http_status_code=400, error_code="ValidationError", error_message="Invalid key_condition_expression.")
        return _err("VALIDATION_ERROR", "Invalid key_condition_expression.")
    if filter_expression is not None and not isinstance(filter_expression, str):
        _log_request("query-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "filter_expression": filter_expression}, http_status_code=400, error_code="ValidationError", error_message="Invalid filter_expression.")
        return _err("VALIDATION_ERROR", "Invalid filter_expression.")
    if projection_expression is not None and not isinstance(projection_expression, str):
        _log_request("query-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "projection_expression": projection_expression}, http_status_code=400, error_code="ValidationError", error_message="Invalid projection_expression.")
        return _err("VALIDATION_ERROR", "Invalid projection_expression.")
    if expression_attribute_names is not None:
