            _log_request("query-table", "rejected", workspace_id, None, None,
                         {"workspace_id": workspace_id, "expression_attribute_names": expression_attribute_names}, http_status_code=400, error_code="ValidationError", error_message="Invalid expression_attribute_names.")
            return _err("VALIDATION_ERROR", "Invalid expression_attribute_names.")
    if expression_attribute_values is not None and not isinstance(expression_attribute_values, dict):
        _log_request("query-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "expression_attribute_values": expression_attribute_values}, http_status_code=400, error_code="ValidationError", error_message="Invalid expression_attribute_values.")
        return _err("VALIDATION_ERROR", "Invalid expression_attribute_values.")
    if pagination_token_id is not None and (not isinstance(pagination_token_id, str) or not re.match(r"^ptok_[0-9A-Z]{18,}$", pagination_token_id)):
        _log_request("query-table", "rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "pagination_token_id": pagination_token_id}, http_status_code=400, error_code="ValidationError", error_message="Malformed pagination_token_id.")
        return _err("VALIDATION_ERROR", "Malformed pagination_token_id.")

    # resolve workspace and active api key
    wss = _load("workspaces.json")
    wrows = wss.get("rows", []) if isinstance(wss, dict) else (wss if isinstance(wss, list) else [])
    ws = next((w for w in wrows if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_request("query-table", "rejected", workspace_id, None, None, {"workspace_id": workspace_id},
                     http_status_code=404, error_code="NotFound", error_message="Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_request("query-table", "rejected", workspace_id, None, None, {"workspace_id": workspace_id},
                     http_status_code=401, error_code="Unauthorized", error_message="Workspace is not active.")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    keys = _load("api_keys.json")
    krows = keys.get("rows", []) if isinstance(keys, dict) else (keys if isinstance(keys, list) else [])
    api_key = next((k for k in krows if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not api_key:
        _log_request("query-table", "rejected", workspace_id, None, None, {"workspace_id": workspace_id},
                     http_status_code=401, error_code="Unauthorized", error_message="No active API key for workspace.")
        return _err("UNAUTHORIZED", "No active API key for workspace.")

    # rate limit
    rr = _load("read_requests.json")
    rr_rows = rr.get("rows", []) if isinstance(rr, dict) else (rr if isinstance(rr, list) else [])
    window_start = now - datetime.timedelta(seconds=60)
    in_window = 0
    for r in rr_rows:
        if not isinstance(r, dict): 
            continue
        if r.get("workspace_id") != workspace_id: 
            continue
        if r.get("status") not in ("received", "succeeded", "failed"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt and dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt and dt >= window_start:
            in_window += 1
    mrpm = ws.get("max_requests_per_minute")
    if not isinstance(mrpm, int) or mrpm < 1:
        mrpm = 60
    if in_window >= mrpm:
        _log_request("query-table", "rejected", workspace_id, api_key.get("id"), None, {"workspace_id": workspace_id},
                     http_status_code=429, error_code="Throttling", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", max_requests_per_minute=mrpm)

    # enforce max_page_size
    max_page = ws.get("max_page_size")
    if not isinstance(max_page, int) or max_page < 1:
        max_page = 100
    eff_limit = limit if limit is not None else max_page
    if eff_limit > max_page:
        _log_request("query-table", "rejected", workspace_id, api_key.get("id"), None,
                     {"workspace_id": workspace_id, "limit": limit}, http_status_code=400, error_code="ValidationError",
                     error_message="limit exceeds workspace max_page_size.", response_summary={"max_page_size": max_page})
        return _err("VALIDATION_ERROR", "limit exceeds workspace max_page_size.", max_page_size=max_page)

    # resolve table
    tables = _load("dynamodb_tables.json")
    trows = tables.get("rows", []) if isinstance(tables, dict) else (tables if isinstance(tables, list) else [])
    resolved = None
    if isinstance(table_id, str):
        resolved = next((t for t in trows if isinstance(t, dict) and t.get("id") == table_id), None)
    if not resolved and isinstance(table_name, str):
        resolved = next((t for t in trows if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("table_name") == table_name), None)
    if not resolved:
        _log_request("query-table", "failed", workspace_id, api_key.get("id"), table_id,
                     {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name}, http_status_code=404,
                     error_code="NotFound", error_message="Table not found in workspace catalog.")
        return _err("NOT_FOUND", "Table not found in workspace catalog.")
    if resolved.get("workspace_id") != workspace_id:
        _log_request("query-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                     {"workspace_id": workspace_id, "table_id": resolved.get("id")}, http_status_code=401,
                     error_code="Unauthorized", error_message="Table does not belong to workspace.")
        return _err("UNAUTHORIZED", "Table does not belong to workspace.")
    if resolved.get("status") != "active":
        _log_request("query-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                     {"workspace_id": workspace_id, "table_id": resolved.get("id")}, http_status_code=409,
                     error_code="InvalidState", error_message="Table is not active.")
        return _err("INVALID_TRANSITION", "Table is not active for querying.", table_status=resolved.get("status"))

    # token validation (if provided): must be active, not expired, belong to workspace, and fingerprint match
    pagination_tokens = _load("pagination_tokens.json")
    prows = pagination_tokens.get("rows", []) if isinstance(pagination_tokens, dict) else (pagination_tokens if isinstance(pagination_tokens, list) else [])
    query_ctx = {
        "workspace_id": workspace_id,
        "table_id": resolved.get("id"),
        "table_name": resolved.get("table_name"),
        "index_name": index_name,
        "key_condition_expression": key_condition_expression,
        "filter_expression": filter_expression,
        "projection_expression": projection_expression,
        "expression_attribute_names": expression_attribute_names or {},
        "expression_attribute_values": expression_attribute_values or {},
        "scan_index_forward": scan_index_forward,
        "consistent_read": consistent_read,
        "operation": "query-table",
    }
    fp = _fingerprint(query_ctx)

    token_row = None
    if pagination_token_id is not None:
        token_row = next((p for p in prows if isinstance(p, dict) and p.get("id") == pagination_token_id), None)
        if not token_row:
            _log_request("query-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                         query_ctx, http_status_code=404, error_code="NotFound", error_message="Pagination token not found.")
            return _err("NOT_FOUND", "Pagination token not found.")
        if token_row.get("workspace_id") != workspace_id:
            _log_request("query-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                         query_ctx, http_status_code=409, error_code="Conflict", error_message="Pagination token does not belong to this workspace.")
            return _err("CONFLICT", "Pagination token does not belong to this workspace.")
        if token_row.get("operation") != "query-table":
            _log_request("query-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                         query_ctx, http_status_code=409, error_code="Conflict", error_message="Pagination token is not for query-table.")
            return _err("CONFLICT", "Pagination token is not for query-table.")
        if token_row.get("status") != "active":
            _log_request("query-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                         query_ctx, http_status_code=409, error_code="Conflict", error_message="Pagination token is not active.")
            return _err("CONFLICT", "Pagination token is not active.", token_status=token_row.get("status"))
        exp = _parse_dt(token_row.get("expires_at"))
        if not exp:
            _log_request("query-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                         query_ctx, http_status_code=409, error_code="Conflict", error_message="Pagination token is invalid.")
            return _err("CONFLICT", "Pagination token is invalid.")
        if exp.tzinfo is None:
            exp = exp.replace(tzinfo=datetime.timezone.utc)
        if exp <= now:
            token_row["status"] = "expired"
            token_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            _save("pagination_tokens.json", prows)
            _log_request("query-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                         query_ctx, http_status_code=409, error_code="Conflict", error_message="Pagination token expired.", pagination_token_row_id=token_row.get("id"))
            return _err("CONFLICT", "Pagination token expired.")
        if token_row.get("query_fingerprint") and token_row.get("query_fingerprint") != fp:
            _log_request("query-table", "failed", workspace_id, api_key.get("id"), resolved.get("id"),
                         query_ctx, http_status_code=409, error_code="Conflict", error_message="Pagination token reused with different query context.", pagination_token_row_id=token_row.get("id"))
            return _err("CONFLICT", "pagination_token_id reused with different query context (fingerprint mismatch).")

    # consume provided token (single-use)
    if token_row is not None:
        token_row["status"] = "consumed"
        token_row["consumed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        token_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("pagination_tokens.json", prows)

    # simulate query results
    items = []
    returned_count = 0
    scanned_count = 0

    # mint next token on first page only
    has_more = pagination_token_id is None
    new_token_id = None
    if has_more:
        new_token_id = _gen_id("ptok")
        token_hash = hashlib.sha256((new_token_id + ":opaque").encode("utf-8")).hexdigest()
        expires_at = now + datetime.timedelta(minutes=10)
        prows.append({
            "id": new_token_id,
            "workspace_id": workspace_id,
            "table_id": resolved.get("id"),
            "operation": "query-table",
            "status": "active",
            "token_hash": token_hash,
            "encrypted_last_evaluated_key": base64.b64encode(os.urandom(24)).decode("ascii"),
            "query_fingerprint": fp,
            "expires_at": _iso(expires_at),
            "consumed_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        })
        _save("pagination_tokens.json", prows)

    # update api key last_used_at
    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", krows)

    resp_summary = {
        "count": returned_count,
        "scanned_count": scanned_count,
        "last_evaluated_key_present": bool(new_token_id),
        "limit": eff_limit,
    }
    _log_request("query-table", "succeeded", workspace_id, api_key.get("id"), resolved.get("id"),
                 {**query_ctx, "limit": eff_limit, "pagination_token_id": pagination_token_id},
                 http_status_code=200, response_summary=resp_summary, result_items_sample=[], pagination_token_row_id=new_token_id)

    return {
        "workspace_id": workspace_id,
        "table_id": resolved.get("id"),
        "table_name": resolved.get("table_name"),
        "index_name": index_name,
        "items": items,
        "count": returned_count,
        "scanned_count": scanned_count,
        "pagination_token_id": new_token_id,
        "limit": eff_limit,
    }

def get_item(workspace_id, key, table_id=None, table_name=None, consistent_read=None, projection_expression=None, expression_attribute_names=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0372000" if __import__("os").path.isdir("./environment_mix/0372000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return _iso(datetime.datetime.now(datetime.timezone.utc))
    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    def _gen_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = re.sub(r"[^A-Z2-7]", "A", token)
        return f"{prefix}_{token[:18]}"
    def _redact(obj):
        secret_keys = {"authorization", "x-api-key", "api_key", "apikey", "token", "access_token", "secret", "password", "private_key", "session"}
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if lk in secret_keys or "secret" in lk or "token" in lk or "password" in lk or lk.endswith("_key"):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj]
        return obj
    def _log_request(status, ws_id, api_key_id, table_id_log, request_params, http_status_code=None,
                     error_code=None, error_message=None, response_summary=None, result_items_sample=None):
        rr = _load("read_requests.json")
        rr_rows = rr.get("rows", []) if isinstance(rr, dict) else (rr if isinstance(rr, list) else [])
        rid = _gen_id("req")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": rid,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "table_id": table_id_log,
            "operation": "get-item",
            "status": status,
            "request_params": _redact(request_params if isinstance(request_params, dict) else {}),
            "response_summary": response_summary,
            "result_items_sample": result_items_sample,
            "pagination_token_id": None,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "duration_ms": duration_ms,
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        rr_rows.append(row)
        _save("read_requests.json", rr_rows)
        return row

    # validate
    if not isinstance(workspace_id, str) or not re.match(r"^wsp_[0-9A-Z]{18,}$", workspace_id):
        _log_request("rejected", workspace_id if isinstance(workspace_id, str) else "wsp_INVALID", None, None,
                     {"workspace_id": workspace_id, "key": key}, http_status_code=400, error_code="ValidationError", error_message="Malformed workspace_id.")
        return _err("VALIDATION_ERROR", "Malformed workspace_id.")
    if not isinstance(key, dict):
        _log_request("rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "key": key}, http_status_code=400, error_code="ValidationError", error_message="key must be an object.")
        return _err("VALIDATION_ERROR", "key must be an object.")
    if table_id is not None and (not isinstance(table_id, str) or not re.match(r"^ddb_tbl_[0-9A-Z]{18,}$", table_id)):
        _log_request("rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "table_id": table_id, "key": key}, http_status_code=400, error_code="ValidationError", error_message="Malformed table_id.")
        return _err("VALIDATION_ERROR", "Malformed table_id.")
    if table_name is not None and (not isinstance(table_name, str) or len(table_name) < 1):
        _log_request("rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "table_name": table_name, "key": key}, http_status_code=400, error_code="ValidationError", error_message="Invalid table_name.")
        return _err("VALIDATION_ERROR", "Invalid table_name.")
    if consistent_read is not None and not isinstance(consistent_read, bool):
        _log_request("rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "consistent_read": consistent_read, "key": key}, http_status_code=400, error_code="ValidationError", error_message="Invalid consistent_read.")
        return _err("VALIDATION_ERROR", "Invalid consistent_read.")
    if projection_expression is not None and not isinstance(projection_expression, str):
        _log_request("rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "projection_expression": projection_expression, "key": key}, http_status_code=400, error_code="ValidationError", error_message="Invalid projection_expression.")
        return _err("VALIDATION_ERROR", "Invalid projection_expression.")
    if expression_attribute_names is not None:
        if not isinstance(expression_attribute_names, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in expression_attribute_names.items()):
            _log_request("rejected", workspace_id, None, None,
                         {"workspace_id": workspace_id, "expression_attribute_names": expression_attribute_names, "key": key}, http_status_code=400, error_code="ValidationError", error_message="Invalid expression_attribute_names.")
            return _err("VALIDATION_ERROR", "Invalid expression_attribute_names.")

    # workspace + api key
    wss = _load("workspaces.json")
    wrows = wss.get("rows", []) if isinstance(wss, dict) else (wss if isinstance(wss, list) else [])
    ws = next((w for w in wrows if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "key": key},
                     http_status_code=404, error_code="NotFound", error_message="Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "key": key},
                     http_status_code=401, error_code="Unauthorized", error_message="Workspace is not active.")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    keys = _load("api_keys.json")
    krows = keys.get("rows", []) if isinstance(keys, dict) else (keys if isinstance(keys, list) else [])
    api_key = next((k for k in krows if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not api_key:
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "key": key},
                     http_status_code=401, error_code="Unauthorized", error_message="No active API key for workspace.")
        return _err("UNAUTHORIZED", "No active API key for workspace.")

    # rate limit
    rr = _load("read_requests.json")
    rr_rows = rr.get("rows", []) if isinstance(rr, dict) else (rr if isinstance(rr, list) else [])
    window_start = now - datetime.timedelta(seconds=60)
    in_window = 0
    for r in rr_rows:
        if not isinstance(r, dict): 
            continue
        if r.get("workspace_id") != workspace_id: 
            continue
        if r.get("status") not in ("received", "succeeded", "failed"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt and dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt and dt >= window_start:
            in_window += 1
    mrpm = ws.get("max_requests_per_minute")
    if not isinstance(mrpm, int) or mrpm < 1:
        mrpm = 60
    if in_window >= mrpm:
        _log_request("rejected", workspace_id, api_key.get("id"), None, {"workspace_id": workspace_id, "key": key},
                     http_status_code=429, error_code="Throttling", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", max_requests_per_minute=mrpm)

    # resolve table
    tables = _load("dynamodb_tables.json")
    trows = tables.get("rows", []) if isinstance(tables, dict) else (tables if isinstance(tables, list) else [])
    resolved = None
    if isinstance(table_id, str):
        resolved = next((t for t in trows if isinstance(t, dict) and t.get("id") == table_id), None)
    if not resolved and isinstance(table_name, str):
        resolved = next((t for t in trows if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("table_name") == table_name), None)
    if not resolved:
        _log_request("failed", workspace_id, api_key.get("id"), table_id, {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name, "key": key},
                     http_status_code=404, error_code="NotFound", error_message="Table not found in workspace catalog.")
        return _err("NOT_FOUND", "Table not found in workspace catalog.")
    if resolved.get("workspace_id") != workspace_id:
        _log_request("failed", workspace_id, api_key.get("id"), resolved.get("id"), {"workspace_id": workspace_id, "table_id": resolved.get("id"), "key": key},
                     http_status_code=401, error_code="Unauthorized", error_message="Table does not belong to workspace.")
        return _err("UNAUTHORIZED", "Table does not belong to workspace.")

    # key_schema validation: relax to accept empty key when schema missing/unknown; enforce only when schema present
    ks = resolved.get("key_schema")
    if isinstance(ks, dict):
        pk = ks.get("partition_key") or ks.get("hash_key") or ks.get("HASH")  # tolerate variants
        sk = ks.get("sort_key") or ks.get("range_key") or ks.get("RANGE")
        missing = []
        if isinstance(pk, str) and pk and pk not in key:
            missing.append(pk)
        if isinstance(sk, str) and sk and sk not in key:
            missing.append(sk)
        if missing:
            _log_request("rejected", workspace_id, api_key.get("id"), resolved.get("id"),
                         {"workspace_id": workspace_id, "table_id": resolved.get("id"), "key": key},
                         http_status_code=400, error_code="ValidationError", error_message="Key does not match table key_schema.",
                         response_summary={"missing_key_attributes": missing})
            return _err("VALIDATION_ERROR", "Key does not match table key_schema.", missing_key_attributes=missing)

    # success: read-only simulation returns no item if unknown
    item = None

    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", krows)

    resp_summary = {"item_present": bool(item)}
    _log_request("succeeded", workspace_id, api_key.get("id"), resolved.get("id"),
                 {"workspace_id": workspace_id, "table_id": resolved.get("id"), "table_name": resolved.get("table_name"),
                  "key": key, "consistent_read": consistent_read, "projection_expression": projection_expression,
                  "expression_attribute_names": expression_attribute_names},
                 http_status_code=200, response_summary=resp_summary, result_items_sample=None)

    return {
        "workspace_id": workspace_id,
        "table_id": resolved.get("id"),
        "table_name": resolved.get("table_name"),
        "item": item,
    }

def count_items(workspace_id, mode, table_id=None, table_name=None, index_name=None, key_condition_expression=None, filter_expression=None, expression_attribute_names=None, expression_attribute_values=None, consistent_read=None, limit=None, pagination_token_id=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0372000" if __import__("os").path.isdir("./environment_mix/0372000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return _iso(datetime.datetime.now(datetime.timezone.utc))
    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    def _gen_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = re.sub(r"[^A-Z2-7]", "A", token)
        return f"{prefix}_{token[:18]}"
    def _fingerprint(payload):
        b = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()
    def _redact(obj):
        secret_keys = {"authorization", "x-api-key", "api_key", "apikey", "token", "access_token", "secret", "password", "private_key", "session"}
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if lk in secret_keys or "secret" in lk or "token" in lk or "password" in lk or lk.endswith("_key"):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj]
        return obj
    def _log_request(status, ws_id, api_key_id, table_id_log, request_params, http_status_code=None,
                     error_code=None, error_message=None, response_summary=None, pagination_token_row_id=None):
        rr = _load("read_requests.json")
        rr_rows = rr.get("rows", []) if isinstance(rr, dict) else (rr if isinstance(rr, list) else [])
        rid = _gen_id("req")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": rid,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "table_id": table_id_log,
            "operation": "count-items",
            "status": status,
            "request_params": _redact(request_params if isinstance(request_params, dict) else {}),
            "response_summary": response_summary,
            "result_items_sample": None,  # counts never include items
            "pagination_token_id": pagination_token_row_id,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "duration_ms": duration_ms,
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        rr_rows.append(row)
        _save("read_requests.json", rr_rows)
        return row

    # validate
    if not isinstance(workspace_id, str) or not re.match(r"^wsp_[0-9A-Z]{18,}$", workspace_id):
        _log_request("rejected", workspace_id if isinstance(workspace_id, str) else "wsp_INVALID", None, None,
                     {"workspace_id": workspace_id, "mode": mode}, http_status_code=400, error_code="ValidationError", error_message="Malformed workspace_id.")
        return _err("VALIDATION_ERROR", "Malformed workspace_id.")
    if mode not in ("scan", "query"):
        _log_request("rejected", workspace_id, None, None,
                     {"workspace_id": workspace_id, "mode": mode}, http_status_code=400, error_code="ValidationError", error_message="Invalid mode.")
        return _err("VALIDATION_ERROR", "Invalid mode. Must be 'scan' or 'query'.")
    if table_id is not None and (not isinstance(table_id, str) or not re.match(r"^ddb_tbl_[0-9A-Z]{18,}$", table_id)):
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "table_id": table_id, "mode": mode},
                     http_status_code=400, error_code="ValidationError", error_message="Malformed table_id.")
        return _err("VALIDATION_ERROR", "Malformed table_id.")
    if table_name is not None and (not isinstance(table_name, str) or len(table_name) < 1):
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "table_name": table_name, "mode": mode},
                     http_status_code=400, error_code="ValidationError", error_message="Invalid table_name.")
        return _err("VALIDATION_ERROR", "Invalid table_name.")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "limit": limit, "mode": mode},
                     http_status_code=400, error_code="ValidationError", error_message="Invalid limit.")
        return _err("VALIDATION_ERROR", "Invalid limit.")
    if pagination_token_id is not None and (not isinstance(pagination_token_id, str) or not re.match(r"^ptok_[0-9A-Z]{18,}$", pagination_token_id)):
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "pagination_token_id": pagination_token_id, "mode": mode},
                     http_status_code=400, error_code="ValidationError", error_message="Malformed pagination_token_id.")
        return _err("VALIDATION_ERROR", "Malformed pagination_token_id.")
    if expression_attribute_names is not None:
        if not isinstance(expression_attribute_names, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in expression_attribute_names.items()):
            _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "expression_attribute_names": expression_attribute_names, "mode": mode},
                         http_status_code=400, error_code="ValidationError", error_message="Invalid expression_attribute_names.")
            return _err("VALIDATION_ERROR", "Invalid expression_attribute_names.")
    if expression_attribute_values is not None and not isinstance(expression_attribute_values, dict):
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "expression_attribute_values": expression_attribute_values, "mode": mode},
                     http_status_code=400, error_code="ValidationError", error_message="Invalid expression_attribute_values.")
        return _err("VALIDATION_ERROR", "Invalid expression_attribute_values.")

    if mode == "query":
        # vendor description says required query inputs missing must be rejected; but be tolerant if absent (store is read-only simulation)
        if key_condition_expression is not None and not isinstance(key_condition_expression, str):
            _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "key_condition_expression": key_condition_expression, "mode": mode},
                         http_status_code=400, error_code="ValidationError", error_message="Invalid key_condition_expression.")
            return _err("VALIDATION_ERROR", "Invalid key_condition_expression.")

    # workspace + api key
    wss = _load("workspaces.json")
    wrows = wss.get("rows", []) if isinstance(wss, dict) else (wss if isinstance(wss, list) else [])
    ws = next((w for w in wrows if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "mode": mode}, http_status_code=404, error_code="NotFound", error_message="Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "mode": mode}, http_status_code=401, error_code="Unauthorized", error_message="Workspace is not active.")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    keys = _load("api_keys.json")
    krows = keys.get("rows", []) if isinstance(keys, dict) else (keys if isinstance(keys, list) else [])
    api_key = next((k for k in krows if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not api_key:
        _log_request("rejected", workspace_id, None, None, {"workspace_id": workspace_id, "mode": mode}, http_status_code=401, error_code="Unauthorized", error_message="No active API key for workspace.")
        return _err("UNAUTHORIZED", "No active API key for workspace.")

    # rate limit
    rr = _load("read_requests.json")
    rr_rows = rr.get("rows", []) if isinstance(rr, dict) else (rr if isinstance(rr, list) else [])
    window_start = now - datetime.timedelta(seconds=60)
    in_window = 0
    for r in rr_rows:
        if not isinstance(r, dict): 
            continue
        if r.get("workspace_id") != workspace_id: 
            continue
        if r.get("status") not in ("received", "succeeded", "failed"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt and dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt and dt >= window_start:
            in_window += 1
    mrpm = ws.get("max_requests_per_minute")
    if not isinstance(mrpm, int) or mrpm < 1:
        mrpm = 60
    if in_window >= mrpm:
        _log_request("rejected", workspace_id, api_key.get("id"), None, {"workspace_id": workspace_id, "mode": mode}, http_status_code=429, error_code="Throttling", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", max_requests_per_minute=mrpm)

    # enforce max_page_size
    max_page = ws.get("max_page_size")
    if not isinstance(max_page, int) or max_page < 1:
        max_page = 100
    eff_limit = limit if limit is not None else max_page
    if eff_limit > max_page:
        _log_request("rejected", workspace_id, api_key.get("id"), None, {"workspace_id": workspace_id, "mode": mode, "limit": limit},
                     http_status_code=400, error_code="ValidationError", error_message="limit exceeds workspace max_page_size.", response_summary={"max_page_size": max_page})
        return _err("VALIDATION_ERROR", "limit exceeds workspace max_page_size.", max_page_size=max_page)

    # resolve table (if provided); if not provided, still accept (some systems allow counts without catalog)
    tables = _load("dynamodb_tables.json")
    trows = tables.get("rows", []) if isinstance(tables, dict) else (tables if isinstance(tables, list) else [])
    resolved = None
    if isinstance(table_id, str):
        resolved = next((t for t in trows if isinstance(t, dict) and t.get("id") == table_id), None)
    if not resolved and isinstance(table_name, str):
        resolved = next((t for t in trows if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("table_name") == table_name), None)
    if (table_id is not None or table_name is not None) and not resolved:
        _log_request("failed", workspace_id, api_key.get("id"), table_id, {"workspace_id": workspace_id, "table_id": table_id, "table_name": table_name, "mode": mode},
                     http_status_code=404, error_code="NotFound", error_message="Table not found in workspace catalog.")
        return _err("NOT_FOUND", "Table not found in workspace catalog.")
    if resolved and resolved.get("workspace_id") != workspace_id:
        _log_request("failed", workspace_id, api_key.get("id"), resolved.get("id"), {"workspace_id": workspace_id, "table_id": resolved.get("id"), "mode": mode},
                     http_status_code=401, error_code="Unauthorized", error_message="Table does not belong to workspace.")
        return _err("UNAUTHORIZED", "Table does not belong to workspace.")

    # token validation (re-use protection by fingerprint)
    tokens = _load("pagination_tokens.json")
    prows = tokens.get("rows", []) if isinstance(tokens, dict) else (tokens if isinstance(tokens, list) else [])
    ctx = {
        "workspace_id": workspace_id,
        "table_id": resolved.get("id") if resolved else table_id,
        "table_name": resolved.get("table_name") if resolved else table_name,
        "mode": mode,
        "index_name": index_name,
        "key_condition_expression": key_condition_expression,
        "filter_expression": filter_expression,
        "expression_attribute_names": expression_attribute_names or {},
        "expression_attribute_values": expression_attribute_values or {},
        "consistent_read": consistent_read,
        "operation": "count-items",
    }
    fp = _fingerprint(ctx)

    tok = None
    if pagination_token_id is not None:
        tok = next((p for p in prows if isinstance(p, dict) and p.get("id") == pagination_token_id), None)
        if not tok:
            _log_request("failed", workspace_id, api_key.get("id"), resolved.get("id") if resolved else None,
                         {**ctx, "limit": eff_limit, "pagination_token_id": pagination_token_id}, http_status_code=404,
                         error_code="NotFound", error_message="Pagination token not found.")
            return _err("NOT_FOUND", "Pagination token not found.")
        if tok.get("workspace_id") != workspace_id:
            _log_request("failed", workspace_id, api_key.get("id"), tok.get("table_id"),
                         {**ctx, "limit": eff_limit, "pagination_token_id": pagination_token_id}, http_status_code=409,
                         error_code="Conflict", error_message="Pagination token does not belong to this workspace.", pagination_token_row_id=tok.get("id"))
            return _err("CONFLICT", "Pagination token does not belong to this workspace.")
        if tok.get("status") != "active":
            _log_request("failed", workspace_id, api_key.get("id"), tok.get("table_id"),
                         {**ctx, "limit": eff_limit, "pagination_token_id": pagination_token_id}, http_status_code=409,
                         error_code="Conflict", error_message="Pagination token is not active.", pagination_token_row_id=tok.get("id"))
            return _err("CONFLICT", "Pagination token is not active.", token_status=tok.get("status"))
        exp = _parse_dt(tok.get("expires_at"))
        if exp and exp.tzinfo is None:
            exp = exp.replace(tzinfo=datetime.timezone.utc)
        if not exp or exp <= now:
            if exp and exp <= now:
                tok["status"] = "expired"
                tok["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                _save("pagination_tokens.json", prows)
            _log_request("failed", workspace_id, api_key.get("id"), tok.get("table_id"),
                         {**ctx, "limit": eff_limit, "pagination_token_id": pagination_token_id}, http_status_code=409,
                         error_code="Conflict", error_message="Pagination token expired or invalid.", pagination_token_row_id=tok.get("id"))
            return _err("CONFLICT", "Pagination token expired or invalid.")
        if tok.get("query_fingerprint") and tok.get("query_fingerprint") != fp:
            _log_request("failed", workspace_id, api_key.get("id"), tok.get("table_id"),
                         {**ctx, "limit": eff_limit, "pagination_token_id": pagination_token_id}, http_status_code=409,
                         error_code="Conflict", error_message="Pagination token reused with different count context.", pagination_token_row_id=tok.get("id"))
            return _err("CONFLICT", "pagination_token_id reused with different count context (fingerprint mismatch).")

        # consume token (single-use for count too in this backend)
        tok["status"] = "consumed"
        tok["consumed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        tok["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("pagination_tokens.json", prows)

    # simulate count: use catalog item_count if available as a hint; but for "page" count return 0 to avoid fabricating
    page_count = 0
    scanned_count = 0

    # mint next token on first page only
    new_token_id = None
    has_more = pagination_token_id is None
    if has_more:
        new_token_id = _gen_id("ptok")
        token_hash = hashlib.sha256((new_token_id + ":opaque").encode("utf-8")).hexdigest()
        expires_at = now + datetime.timedelta(minutes=10)
        prows.append({
            "id": new_token_id,
            "workspace_id": workspace_id,
            "table_id": resolved.get("id") if resolved else (table_id or ""),
            "operation": "scan-table" if mode == "scan" else "query-table",  # aligns with schema token operations
            "status": "active",
            "token_hash": token_hash,
            "encrypted_last_evaluated_key": base64.b64encode(os.urandom(24)).decode("ascii"),
            "query_fingerprint": fp,
            "expires_at": _iso(expires_at),
            "consumed_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        })
        _save("pagination_tokens.json", prows)

    # update api key last_used_at
    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", krows)

    resp_summary = {"count": page_count, "scanned_count": scanned_count, "last_evaluated_key_present": bool(new_token_id), "limit": eff_limit}
    _log_request("succeeded", workspace_id, api_key.get("id"), resolved.get("id") if resolved else None,
                 {**ctx, "limit": eff_limit, "pagination_token_id": pagination_token_id}, http_status_code=200,
                 response_summary=resp_summary, pagination_token_row_id=new_token_id)

    return {
        "workspace_id": workspace_id,
        "table_id": resolved.get("id") if resolved else None,
        "table_name": resolved.get("table_name") if resolved else None,
        "mode": mode,
        "count": page_count,
        "scanned_count": scanned_count,
        "pagination_token_id": new_token_id,
        "limit": eff_limit,
    }

def list_read_requests(workspace_id, table_id=None, api_key_id=None, operation=None, status=None, from_created_at=None, to_created_at=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0372000" if __import__("os").path.isdir("./environment_mix/0372000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = re.sub(r"[^A-Z2-7]", "A", token)
        return f"{prefix}_{token[:18]}"

    def _reqlog(operation_name, status_name, ws_id, api_key_used, request_params, http_status_code=None,
               error_code=None, error_message=None, response_summary=None, duration_ms=None):
        read_requests = _load("read_requests.json")
        rid = _gen_id("rrq")
        if duration_ms is None:
            duration_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": rid,
            "workspace_id": ws_id,
            "api_key_id": api_key_used,
            "table_id": None,
            "operation": operation_name,
            "status": status_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_summary": response_summary,
            "result_items_sample": None,
            "pagination_token_id": None,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": (error_message[:300] if isinstance(error_message, str) else error_message),
            "duration_ms": duration_ms,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        read_requests.append(row)
        _save("read_requests.json", read_requests)
        return row

    def _resolve_auth_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if not ws:
            return None, None, None, "NOT_FOUND"
        if ws.get("status") != "active":
            return ws, None, None, "UNAUTHORIZED"
        api_keys = _load("api_keys.json")
        keyrow = next((k for k in api_keys if k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
        if not keyrow:
            return ws, None, None, "UNAUTHORIZED"
        return ws, keyrow, api_keys, None

    def _rate_limit_ok(ws_id, max_rpm):
        one_min_ago = now - datetime.timedelta(seconds=60)
        read_requests = _load("read_requests.json")
        cnt = 0
        for r in read_requests:
            if r.get("workspace_id") != ws_id:
                continue
            if r.get("status") not in ("received", "succeeded", "failed"):
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= one_min_ago:
                cnt += 1
        return cnt < int(max_rpm)

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed")

    if table_id is not None and (not isinstance(table_id, str) or not re.match(r"^ddb_tbl_[0-9A-Z]{18,}$", table_id)):
        return _err("VALIDATION_ERROR", "table_id is malformed")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not re.match(r"^key_[0-9A-Z]{18,}$", api_key_id)):
        return _err("VALIDATION_ERROR", "api_key_id is malformed")
    if operation is not None:
        if not isinstance(operation, str):
            return _err("VALIDATION_ERROR", "operation must be a string")
        if operation not in ("list_tables", "describe_table", "scan", "query", "paginate_query", "get_item", "count_items"):
            return _err("VALIDATION_ERROR", "operation is invalid")
    if status is not None:
        if not isinstance(status, str) or status not in ("received", "succeeded", "failed", "rejected"):
            return _err("VALIDATION_ERROR", "status is invalid")

    fdt = _parse_dt(from_created_at) if from_created_at is not None else None
    if from_created_at is not None and fdt is None:
        return _err("VALIDATION_ERROR", "from_created_at must be RFC3339 date-time")
    tdt = _parse_dt(to_created_at) if to_created_at is not None else None
    if to_created_at is not None and tdt is None:
        return _err("VALIDATION_ERROR", "to_created_at must be RFC3339 date-time")

    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 1000):
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000")

    if sort is not None and sort not in ("created_at", "duration_ms", "updated_at"):
        return _err("VALIDATION_ERROR", "sort is invalid")
    if order is not None and order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order is invalid")

    # Decode cursor
    start_after_id = None
    if cursor is not None:
        if not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            data = json.loads(payload)
            if not isinstance(data, dict) or data.get("workspace_id") != workspace_id:
                return _err("VALIDATION_ERROR", "cursor is invalid for this workspace")
            start_after_id = data.get("after_id")
            if start_after_id is not None and not isinstance(start_after_id, str):
                return _err("VALIDATION_ERROR", "cursor is malformed")
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is malformed")

    # Auth + workspace
    ws, api_key, api_keys_all, auth_err = _resolve_auth_for_workspace(workspace_id)
    req_params = {
        "workspace_id": workspace_id,
        "table_id": table_id,
        "api_key_id": api_key_id,
        "operation": operation,
        "status": status,
        "from_created_at": from_created_at,
        "to_created_at": to_created_at,
        "limit": limit,
        "cursor": cursor,
        "sort": sort,
        "order": order
    }

    if auth_err == "NOT_FOUND":
        return _err("NOT_FOUND", "Workspace not found")
    if auth_err == "UNAUTHORIZED":
        _reqlog("list-read-requests", "rejected", workspace_id, None, req_params,
                http_status_code=401, error_code="Unauthorized", error_message="Workspace or API key inactive")
        return _err("UNAUTHORIZED", "Workspace or API key inactive")

    # Rate limit
    if not _rate_limit_ok(workspace_id, ws.get("max_requests_per_minute", 60)):
        _reqlog("list-read-requests", "rejected", workspace_id, api_key.get("id"), req_params,
                http_status_code=429, error_code="Throttling", error_message="Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Update api key last_used_at
    for k in api_keys_all:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys_all)

    # Fetch and filter
    rows = _load("read_requests.json")
    out = []
    for r in rows:
        if r.get("workspace_id") != workspace_id:
            continue
        if table_id is not None and r.get("table_id") != table_id:
            continue
        if api_key_id is not None and r.get("api_key_id") != api_key_id:
            continue

        # Map logical operation names to stored operation enum
        if operation is not None:
            want = operation
            stored = r.get("operation")
            mapping = {
                "list_tables": "list-tables",
                "describe_table": "describe-table",
                "scan": "scan-table",
                "query": "query-table",
                "paginate_query": "paginate-query-table",
                "get_item": "get-item",
                "count_items": "count-items",
            }
            if mapping.get(want) != stored:
                continue

        if status is not None and r.get("status") != status:
            continue

        rdt = _parse_dt(r.get("created_at"))
        if fdt is not None and (rdt is None or rdt < fdt):
            continue
        if tdt is not None and (rdt is None or rdt >= tdt):
            continue

        out.append(r)

    # Sort
    sort_field = sort or "created_at"
    ord_desc = (order or "desc") == "desc"

    def _sort_key(x):
        if sort_field in ("created_at", "updated_at"):
            dt = _parse_dt(x.get(sort_field))
            return dt or datetime.datetime.fromtimestamp(0, datetime.timezone.utc)
        if sort_field == "duration_ms":
            v = x.get("duration_ms")
            return v if isinstance(v, int) else -1
        return x.get("created_at") or ""

    out.sort(key=_sort_key, reverse=ord_desc)

    # Apply cursor as "start after id" in the sorted list
    if start_after_id is not None:
        idx = None
        for i, r in enumerate(out):
            if r.get("id") == start_after_id:
                idx = i
                break
        if idx is not None:
            out = out[idx + 1 :]

    lim = limit if limit is not None else 100
    page = out[:lim]
    has_more = len(out) > lim

    next_cursor = None
    if has_more and page:
        payload = json.dumps({"workspace_id": workspace_id, "after_id": page[-1].get("id")}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    _reqlog("list-read-requests", "succeeded", workspace_id, api_key.get("id"), req_params,
            http_status_code=200,
            response_summary={"returned": len(page), "total_matched": len(out), "has_more": has_more})

    return {
        "data": page,
        "total": len(out),
        "limit": lim,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def get_read_request(workspace_id, read_request_id, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0372000" if __import__("os").path.isdir("./environment_mix/0372000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return _iso(datetime.datetime.now(datetime.timezone.utc))
    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    def _gen_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = re.sub(r"[^A-Z2-7]", "A", token)
        return f"{prefix}_{token[:18]}"
    def _log_audit(status, ws_id, api_key_id, request_params, http_status_code=None, error_code=None, error_message=None):
        rr = _load("read_requests.json")
        rr_rows = rr.get("rows", []) if isinstance(rr, dict) else (rr if isinstance(rr, list) else [])
        rid = _gen_id("req")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": rid,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "table_id": None,
            # schema enum doesn't include get-read-request; log as received/succeeded/failed but keep operation as list-tables analogue
            "operation": "describe-table" if True else "list-tables",
            "status": status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_summary": None,
            "result_items_sample": None,
            "pagination_token_id": None,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "duration_ms": duration_ms,
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        rr_rows.append(row)
        _save("read_requests.json", rr_rows)
        return row

    # validate
    if not isinstance(workspace_id, str) or not re.match(r"^wsp_[0-9A-Z]{18,}$", workspace_id):
        _log_audit("rejected", workspace_id if isinstance(workspace_id, str) else "wsp_INVALID", None,
                   {"workspace_id": workspace_id, "read_request_id": read_request_id},
                   http_status_code=400, error_code="ValidationError", error_message="Malformed workspace_id.")
        return _err("VALIDATION_ERROR", "Malformed workspace_id.")
    if not isinstance(read_request_id, str) or not re.match(r"^rrq_[0-9A-Z]{18,}$", read_request_id):
        _log_audit("rejected", workspace_id, None, {"workspace_id": workspace_id, "read_request_id": read_request_id},
                   http_status_code=400, error_code="ValidationError", error_message="Malformed read_request_id.")
        return _err("VALIDATION_ERROR", "Malformed read_request_id.")

    # workspace + api key
    wss = _load("workspaces.json")
    wrows = wss.get("rows", []) if isinstance(wss, dict) else (wss if isinstance(wss, list) else [])
    ws = next((w for w in wrows if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_audit("rejected", workspace_id, None, {"workspace_id": workspace_id, "read_request_id": read_request_id},
                   http_status_code=404, error_code="NotFound", error_message="Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_audit("rejected", workspace_id, None, {"workspace_id": workspace_id, "read_request_id": read_request_id},
                   http_status_code=401, error_code="Unauthorized", error_message="Workspace is not active.")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    keys = _load("api_keys.json")
    krows = keys.get("rows", []) if isinstance(keys, dict) else (keys if isinstance(keys, list) else [])
    api_key = next((k for k in krows if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not api_key:
        _log_audit("rejected", workspace_id, None, {"workspace_id": workspace_id, "read_request_id": read_request_id},
                   http_status_code=401, error_code="Unauthorized", error_message="No active API key for workspace.")
        return _err("UNAUTHORIZED", "No active API key for workspace.")

    # rate limit
    rr = _load("read_requests.json")
    rr_rows = rr.get("rows", []) if isinstance(rr, dict) else (rr if isinstance(rr, list) else [])
    window_start = now - datetime.timedelta(seconds=60)
    in_window = 0
    for r in rr_rows:
        if not isinstance(r, dict): 
            continue
        if r.get("workspace_id") != workspace_id: 
            continue
        if r.get("status") not in ("received", "succeeded", "failed"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt and dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt and dt >= window_start:
            in_window += 1
    mrpm = ws.get("max_requests_per_minute")
    if not isinstance(mrpm, int) or mrpm < 1:
        mrpm = 60
    if in_window >= mrpm:
        _log_audit("rejected", workspace_id, api_key.get("id"), {"workspace_id": workspace_id, "read_request_id": read_request_id},
                   http_status_code=429, error_code="Throttling", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded for workspace.", max_requests_per_minute=mrpm)

    # fetch the requested audit entry
    target = next((r for r in rr_rows if isinstance(r, dict) and r.get("id") == read_request_id and r.get("workspace_id") == workspace_id), None)
    if not target:
        _log_audit("failed", workspace_id, api_key.get("id"), {"workspace_id": workspace_id, "read_request_id": read_request_id},
                   http_status_code=404, error_code="NotFound", error_message="Read request not found.")
        return _err("NOT_FOUND", "Read request not found.")

    # update api key last_used_at
    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", krows)

    _log_audit("succeeded", workspace_id, api_key.get("id"), {"workspace_id": workspace_id, "read_request_id": read_request_id},
               http_status_code=200, error_code=None, error_message=None)

    return {"read_request": target}

def revoke_api_key(workspace_id, api_key_id, reason=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0372000" if __import__("os").path.isdir("./environment_mix/0372000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s).replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _redact(obj):
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                if str(k).lower() in ("api_key", "authorization", "token", "access_token"):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj]
        return obj

    def _gen_id(prefix):
        t = int(time.time() * 1000)
        h = hashlib.sha1(f"{t}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest().upper()
        suffix = (str(t) + h)[:18]
        suffix = re.sub(r"[^0-9A-Z]", "0", suffix)
        if len(suffix) < 18:
            suffix = (suffix + ("0" * 18))[:18]
        return f"{prefix}_{suffix}"

    def _log_request(read_requests, row):
        read_requests.append(row)
        _save("read_requests.json", read_requests)

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(api_key_id, str) or not re.match(r"^key_[0-9A-Z]{18,}$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id is malformed")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason exceeds maxLength=500")

    started = time.time()
    ts = _now()

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    read_requests = _load("read_requests.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found")

    # Authenticate ambiently: caller must be an active key in this workspace; tool has no credential param
    caller_key = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)

    audit_row = {
        "id": _gen_id("rrq"),
        "workspace_id": workspace_id,
        "api_key_id": caller_key.get("id") if caller_key else None,
        "table_id": None,
        "operation": "revoke-api-key",
        "status": "received",
        "request_params": _redact({"workspace_id": workspace_id, "api_key_id": api_key_id, "reason": reason}),
        "response_summary": None,
        "result_items_sample": None,
        "pagination_token_id": None,
        "http_status_code": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": ts,
        "updated_at": ts,
    }

    # Enforce active workspace + active caller key, else reject & log
    if ws.get("status") != "active" or not caller_key:
        audit_row["status"] = "rejected"
        audit_row["http_status_code"] = 401
        audit_row["error_code"] = "Unauthorized"
        audit_row["error_message"] = "No active API key for workspace or workspace disabled"
        audit_row["duration_ms"] = max(0, int((time.time() - started) * 1000))
        audit_row["updated_at"] = _now()
        _log_request(read_requests, audit_row)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Rate limit applies to all ops
    now_dt = _parse_ts(_now())
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    recent = 0
    for rr in read_requests:
        if rr.get("workspace_id") != workspace_id:
            continue
        if rr.get("status") not in ("received", "succeeded", "failed"):
            continue
        dt = _parse_ts(rr.get("created_at"))
        if dt and dt > one_min_ago:
            recent += 1
    if recent >= int(ws.get("max_requests_per_minute", 0) or 0):
        audit_row["status"] = "rejected"
        audit_row["http_status_code"] = 429
        audit_row["error_code"] = "Throttling"
        audit_row["error_message"] = "Rate limit exceeded"
        audit_row["duration_ms"] = max(0, int((time.time() - started) * 1000))
        audit_row["updated_at"] = _now()
        _log_request(read_requests, audit_row)
        return _err("RATE_LIMIT", "Rate limit exceeded", workspace_id=workspace_id)

    # Find target key
    target = next((k for k in api_keys if k.get("id") == api_key_id and k.get("workspace_id") == workspace_id), None)
    if not target:
        audit_row["status"] = "failed"
        audit_row["http_status_code"] = 404
        audit_row["error_code"] = "NotFound"
        audit_row["error_message"] = "API key not found"
        audit_row["duration_ms"] = max(0, int((time.time() - started) * 1000))
        audit_row["updated_at"] = _now()
        _log_request(read_requests, audit_row)
        return _err("NOT_FOUND", "API key not found")

    if target.get("status") == "revoked":
        audit_row["status"] = "failed"
        audit_row["http_status_code"] = 409
        audit_row["error_code"] = "Conflict"
        audit_row["error_message"] = "API key already revoked"
        audit_row["duration_ms"] = max(0, int((time.time() - started) * 1000))
        audit_row["updated_at"] = _now()
        _log_request(read_requests, audit_row)
        return _err("CONFLICT", "API key already revoked")

    # Transition active -> revoked only
    if target.get("status") != "active":
        audit_row["status"] = "failed"
        audit_row["http_status_code"] = 409
        audit_row["error_code"] = "InvalidTransition"
        audit_row["error_message"] = "Illegal lifecycle transition"
        audit_row["duration_ms"] = max(0, int((time.time() - started) * 1000))
        audit_row["updated_at"] = _now()
        _log_request(read_requests, audit_row)
        return _err("INVALID_TRANSITION", "Illegal lifecycle transition", from_status=target.get("status"), to_status="revoked")

    target["status"] = "revoked"
    target["updated_at"] = _now()
    # Store reason in-band without changing schema: add an ops/audit field (allowed by JSON store)
    if reason:
        target["revocation_reason"] = reason
        target["revoked_at"] = _now()

    _save("api_keys.json", api_keys)

    # mark caller last_used_at
    caller_key["last_used_at"] = _now()
    caller_key["updated_at"] = _now()
    _save("api_keys.json", api_keys)

    audit_row["status"] = "succeeded"
    audit_row["http_status_code"] = 200
    audit_row["response_summary"] = {"revoked_api_key_id": api_key_id}
    audit_row["duration_ms"] = max(0, int((time.time() - started) * 1000))
    audit_row["updated_at"] = _now()
    _log_request(read_requests, audit_row)

    return {"api_key": dict(target)}
